  1	/* ============================================================
  2	   views/project-detail.js — Project Detail view
  3	   Sections 4b–4d of the MCP Server Dashboard SPA
  4	   Depends on: API, Router, marked, escapeHtml, formatDate,
  5	               statusBadge, showLoading, showError,
  6	               OrchestratorWidgets (js/orchestrator-widgets.js),
  7	               UI (components.js)
  8	   ============================================================ */
  9	
 10	// Module-scoped log-preview cleanup registry.
 11	// Each renderProjectDetail() call drains this array before creating new widgets.
 12	var _pdLogPreviewCleanups = [];
 13	
 14	/* ----------------------------------------------------------
 15	   4b. View: Plan Document
 16	   ---------------------------------------------------------- */
 17	function extractSynopsis(markdown) {
 18	  var match = markdown.match(/## Summary\s*\n([\s\S]*?)(?=\n## |\n---|\s*$)/);
 19	  return match ? match[1].trim() : null;
 20	}
 21	
 22	async function renderPlan(app, repo, slug) {
 23	  app.innerHTML = '<p class="loading">Loading plan\u2026</p>';
 24	  try {
 25	    var result = await API.getPlanDocument(repo, slug);
 26	    var html = marked.parse(result.content);
 27	    app.innerHTML =
 28	      breadcrumb().projects().project(repo, slug).leaf('Plan').html() +
 29	      '<div class="plan-content">' + html + '</div>';
 30	  } catch (err) {
 31	    if (err && err.code === 'NOT_FOUND') {
 32	      app.innerHTML =
 33	        breadcrumb().projects().project(repo, slug).leaf('Plan').html() +
 34	        '<p class="empty-state">Plan document not available for this project.</p>';
 35	    } else {
 36	      app.innerHTML = UI.banner('error', 'Failed to load plan document.');
 37	    }
 38	  }
 39	}
 40	
 41	/* ----------------------------------------------------------
 42	   4b-ii. View: Synthesis Document
 43	   ---------------------------------------------------------- */
 44	async function renderSynthesis(app, repo, slug) {
 45	  app.innerHTML = '<p class="loading">Loading synthesis\u2026</p>';
 46	  try {
 47	    var result = await API.getSynthesisDocument(repo, slug);
 48	    var html = marked.parse(result.content);
 49	    app.innerHTML =
 50	      breadcrumb().projects().project(repo, slug).leaf('Synthesis').html() +
 51	      '<div class="synthesis-content">' + html + '</div>';
 52	  } catch (err) {
 53	    if (err && err.code === 'NOT_FOUND') {
 54	      app.innerHTML =
 55	        breadcrumb().projects().project(repo, slug).leaf('Synthesis').html() +
 56	        '<p class="empty-state">Synthesis document not available for this project.</p>';
 57	    } else {
 58	      app.innerHTML = UI.banner('error', 'Failed to load synthesis document.');
 59	    }
 60	  }
 61	}
 62	
 63	/* ----------------------------------------------------------
 64	   4c. View: Project Detail
 65	   ---------------------------------------------------------- */
 66	
 67	// Abbreviations for pipeline stage types
 68	var STAGE_ABBREV = {
 69	  'implementation':     'DEV',
 70	  'qa':                 'QA',
 71	  'security-audit':     'SEC',
 72	  'code-review':        'REV',
 73	  'release-engineering':'REL',
 74	  'documentation':      'DOC'
 75	};
 76	
 77	function buildPipelineTrack(overviewEntry) {
 78	  if (!overviewEntry || !overviewEntry.pipeline_stages || !overviewEntry.pipeline_stages.length) {
 79	    return '—';
 80	  }
 81	  var badges = overviewEntry.pipeline_stages.map(function (stage) {
 82	    var abbrev = STAGE_ABBREV[stage.type] || stage.type.slice(0, 3).toUpperCase();
 83	    var statusClass = 'stage-pending';
 84	    if (stage.status === 'in-progress') statusClass = 'stage-in-progress';
 85	    else if (stage.status === 'pass')        statusClass = 'stage-pass';
 86	    else if (stage.status === 'fail')        statusClass = 'stage-fail';
 87	    var tooltip = escapeHtml(stage.type) + ' — ' + escapeHtml(stage.agent);
 88	    if (stage.rework_count > 0) tooltip += ' (rework: ' + stage.rework_count + ')';
 89	    var reworkBadge = stage.rework_count > 0
 90	      ? '<span class="rework-indicator" title="Rework count: ' + stage.rework_count + '">' + stage.rework_count + '</span>'
 91	      : '';
 92	    return '<span class="stage-badge ' + statusClass + '" title="' + tooltip + '">' +
 93	      escapeHtml(abbrev) +
 94	      reworkBadge +
 95	    '</span>';
 96	  }).join('');
 97	  return '<div class="pipeline-track">' + badges + '</div>';
 98	}
 99	
100	function buildRunBadges(item, isActive) {

101	  var badges = '';
102	  if (isActive) {
103	    badges += '<span class="badge badge-in-progress">Running</span>';
104	  }
105	  if (item && item.is_dry_run) {
106	    badges += '<span class="badge badge-dry-run">Dry Run</span>';
107	  }
108	  return badges;
109	}
110	
111	/* ----------------------------------------------------------
112	   Orchestrator Toolbar
113	   Renders Kill + Resume buttons into toolbarEl.
114	   Always visible; buttons are disabled (with explanatory
115	   tooltips) when the corresponding action is unavailable.
116	
117	   opts: {
118	     loading:      bool,           — show "Loading…" disabled state
119	     hasActiveRun: bool,           — is there an active run?
120	     queueEntry:   object|null,    — matching queue entry (kill)
121	     runMeta:      object|null,    — run metadata (resume)
122	     meta:         object,         — project meta (plan_path, status)
123	     repo:         string,
124	     slug:         string,
125	     app:          Element,        — root element (re-render after resume)
126	     onKillDone:   Function,       — called after a successful kill
127	   }
128	   ---------------------------------------------------------- */
129	function renderOrchToolbar(toolbarEl, opts) {
130	  if (!toolbarEl) return;
131	  toolbarEl.innerHTML = '';
132	
133	  var loading      = !!opts.loading;
134	  var hasActiveRun = !!opts.hasActiveRun;
135	  var queueEntry   = opts.queueEntry  || null;
136	  var runMeta      = opts.runMeta     || null;
137	  var meta         = opts.meta        || {};
138	  var repo         = opts.repo        || '';
139	  var slug         = opts.slug        || '';
140	  var app          = opts.app         || null;
141	  var onKillDone   = typeof opts.onKillDone === 'function' ? opts.onKillDone : null;
142	
143	  // ── Kill button ─────────────────────────────────────────────────────
144	  var killDisabled = true;
145	  var killTitle    = 'Loading\u2026';
146	  if (!loading) {
147	    if (!hasActiveRun) {
148	      killTitle = 'No active run to kill';
149	    } else if (!queueEntry) {
150	      killTitle = 'Run is active but not found in the queue \u2014 use: node scripts/kill-orchestrator.js --force';
151	    } else {
152	      killDisabled = false;
153	      killTitle    = '';
154	    }
155	  }
156	
